/* =========================================================
   FOOTER YEAR & PRELOADER
========================================================= */
function setFooterYear() {
  const yearEl = document.getElementById("current-year");
  if (yearEl) {
    yearEl.textContent = new Date().getFullYear();
  }
}

function hidePreloader() {
  const preloader = document.getElementById("preloader");
  if (preloader && !preloader.classList.contains("hide")) {
    preloader.classList.add("hide");
    requestAnimationFrame(() => {
      window.dispatchEvent(new Event("resize"));
    });
  }
}
/* =========================================================
   INITIALIZATION & LIFECYCLE
========================================================= */
applySavedTheme();

document.addEventListener("DOMContentLoaded", () => {
  if (typeof AOS !== "undefined") {
    AOS.init({
      once: false,
      duration: 500,
    });
  }

  initThemeToggle();
  initMobileMenu();
  initScrollSpy();
  initProjectTabs();
  initProjectCarousel();
  initScrollbarArrows();
  setFooterYear();
  scheduleTyping(TYPE_SPEED);
});

window.addEventListener("load", () => {
  setTimeout(hidePreloader, 500);

  if (typeof AOS !== "undefined") {
    setTimeout(() => AOS.refresh(), 600);
  }
});

setTimeout(hidePreloader, 3000);

window.addEventListener("beforeunload", () => {
  clearTimeout(typingTimer);
  if (sectionObserver) {
    sectionObserver.disconnect();
  }
});

// Mobile touch drag on thumb
  thumb.addEventListener(
    "touchstart",
    (e) => {
      if (!e.touches.length) return;
      isDragging = true;
      dragStartY = e.touches[0].clientY;
      dragStartScroll = window.scrollY || root.scrollTop || 0;
      bar.classList.add("is-dragging");
    },
    { passive: true }
  );

  window.addEventListener(
    "touchmove",
    (e) => {
      if (!isDragging || !e.touches.length) return;
      const deltaY = e.touches[0].clientY - dragStartY;
      const trackHeight = track.clientHeight - thumb.offsetHeight;
      const maxScroll = root.scrollHeight - root.clientHeight;
      if (trackHeight > 0 && maxScroll > 0) {
        window.scrollTo(0, dragStartScroll + (deltaY / trackHeight) * maxScroll);
      }
    },
    { passive: true }
  );

  window.addEventListener("touchend", () => {
    if (!isDragging) return;
    isDragging = false;
    bar.classList.remove("is-dragging");
  });
